import {
  Component,
  EventEmitter,
  Input,
  OnChanges,
  Output,
  SimpleChanges,
} from '@angular/core';
import { CommonModule } from '@angular/common';
import {
  FormBuilder,
  FormGroup,
  ReactiveFormsModule,
  Validators,
} from '@angular/forms';
import { Curso } from '../../models/curso.model';

@Component({
  selector: 'app-curso-form',
  standalone: true,
  imports: [CommonModule, ReactiveFormsModule],
  templateUrl: './curso-form.component.html',
  styleUrl: './curso-form.component.css',
})
export class CursoFormComponent implements OnChanges {
  @Input() curso: Curso | null = null;
  @Output() guardar = new EventEmitter<Curso>();
  @Output() cancelar = new EventEmitter<void>();

  form: FormGroup;

  constructor(private fb: FormBuilder) {
    this.form = this.fb.group({
      nombre: ['', [Validators.required, Validators.minLength(3)]],
      descripcion: ['', [Validators.required, Validators.minLength(10)]],
      instructor: ['', Validators.required],
      categoria: ['', Validators.required],
      duracionHoras: [null, [Validators.required, Validators.min(1)]],
      precio: [null, [Validators.required, Validators.min(0)]],
    });
  }

  ngOnChanges(changes: SimpleChanges): void {
    if (changes['curso']) {
      if (this.curso) {
        this.form.patchValue(this.curso);
      } else {
        this.form.reset();
      }
    }
  }

  get editando(): boolean {
    return !!this.curso?._id;
  }

  campoInvalido(campo: string): boolean {
    const control = this.form.get(campo);
    return !!control && control.invalid && (control.touched || control.dirty);
  }

  onSubmit(): void {
    if (this.form.invalid) {
      this.form.markAllAsTouched();
      return;
    }
    const cursoAGuardar: Curso = {
      ...this.form.value,
      _id: this.curso?._id,
    };
    this.guardar.emit(cursoAGuardar);
    this.form.reset();
  }

  onCancelar(): void {
    this.form.reset();
    this.cancelar.emit();
  }
}
<form class="tarjeta" [formGroup]="form" (ngSubmit)="onSubmit()">
  <h2>{{ editando ? 'Editar curso' : 'Registrar nuevo curso' }}</h2>

  <div class="grid">
    <div class="campo">
      <label for="nombre">Nombre del curso</label>
      <input id="nombre" type="text" formControlName="nombre" placeholder="Ej: Angular Avanzado" />
      <small class="error" *ngIf="campoInvalido('nombre')">Ingresa un nombre de al menos 3 caracteres.</small>
    </div>

    <div class="campo">
      <label for="instructor">Instructor</label>
      <input id="instructor" type="text" formControlName="instructor" placeholder="Ej: María Torres" />
      <small class="error" *ngIf="campoInvalido('instructor')">El instructor es obligatorio.</small>
    </div>

    <div class="campo">
      <label for="categoria">Categoría</label>
      <input id="categoria" type="text" formControlName="categoria" placeholder="Ej: Desarrollo Web" />
      <small class="error" *ngIf="campoInvalido('categoria')">La categoría es obligatoria.</small>
    </div>

    <div class="campo">
      <label for="duracionHoras">Duración (horas)</label>
      <input id="duracionHoras" type="number" formControlName="duracionHoras" min="1" />
      <small class="error" *ngIf="campoInvalido('duracionHoras')">Ingresa una duración válida.</small>
    </div>

    <div class="campo">
      <label for="precio">Precio (S/)</label>
      <input id="precio" type="number" formControlName="precio" min="0" step="0.01" />
      <small class="error" *ngIf="campoInvalido('precio')">Ingresa un precio válido.</small>
    </div>

    <div class="campo campo-ancho">
      <label for="descripcion">Descripción</label>
      <textarea id="descripcion" formControlName="descripcion" rows="3" placeholder="Breve descripción del contenido del curso"></textarea>
      <small class="error" *ngIf="campoInvalido('descripcion')">Ingresa al menos 10 caracteres.</small>
    </div>
  </div>

  <div class="acciones">
    <button type="submit" class="btn btn-primario">
      {{ editando ? 'Guardar cambios' : 'Registrar curso' }}
    </button>
    <button type="button" class="btn btn-secundario" *ngIf="editando" (click)="onCancelar()">
      Cancelar
    </button>
  </div>
</form>
